// Small helper: parallel for_each over a traverser using OpenMP
// -----------------------------------------------------------------------------
template<typename Traverser, typename Func>
inline void omp_trav_for_each(const Traverser &trav, const Func &func) {
	// Parallelize the topmost traversed dimension.
	// If OpenMP is disabled, the pragma is ignored and this runs serially.
	#pragma omp parallel for schedule(static)
	for (auto subtrav : trav.range()) {
		// subtrav is a traverser with one dimension fixed
		subtrav.for_each(func);
	}
}

// -----------------------------------------------------------------------------
// initialization function
// -----------------------------------------------------------------------------
void init_array(auto A, auto B) {
	using namespace noarr;

	// Spatial extent (same for A and B)
	const auto n = A | get_length<'i'>();
	const num_t n_recip = num_t(1) / static_cast<num_t>(n); // precompute 1/n to avoid per-element division

	traverser(A, B).for_each([&](auto state) {
		const auto i = get_index<'i'>(state);
		const num_t i_val = static_cast<num_t>(i);

		// A[i] = (i + 2) / n
		A[state] = (i_val + num_t(2)) * n_recip;
		// B[i] = (i + 3) / n
		B[state] = (i_val + num_t(3)) * n_recip;
	});
}

// -----------------------------------------------------------------------------
// computation kernel
// Jacobi 1D:
//   For each time step:
//     B[i] = (A[i-1] + A[i] + A[i+1]) * c
//     A[i] = (B[i-1] + B[i] + B[i+1]) * c
// Only interior points i in [1, n-2] are updated.
// -----------------------------------------------------------------------------
[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_1d(int tsteps, auto A, auto B) {
	using namespace noarr;

	// spatial problem size
	const auto n = A | get_length<'i'>();

	// constant coefficient (same literal as in the original code)
	const num_t weight = static_cast<num_t>(0.33333);

	// structure used only to iterate over time steps
	auto time_struct = noarr::scalar<num_t>() ^ noarr::vector<'t'>(tsteps);

	// view selecting interior points i in [1, n-2]
	auto interior = noarr::slice<'i'>(1, n - 2);

	// Pre-build traversers over the interior for both sweeps.
	// They are layout-agnostic: any change done through tuning.{a,b}_layout
	// is automatically respected.
	auto trav_B_from_A = traverser(B, A).order(interior);
	auto trav_A_from_B = traverser(A, B).order(interior);

	#pragma scop
	traverser(time_struct).for_each([&](auto /*t_state*/) {

		// -----------------------------------------------------------------
		// First sweep: update B from A over the interior points
		// -----------------------------------------------------------------
		omp_trav_for_each(trav_B_from_A, [&](auto state) {
			// state encodes index i; build neighbor states i-1 and i+1
			const auto left_state  = state - noarr::idx<'i'>(1);
			const auto right_state = state + noarr::idx<'i'>(1);

			// Load neighbors once to improve re-use and reduce address
			// computation overhead from repeated A[state]-like calls.
			const num_t left_val   = A[left_state];
			const num_t center_val = A[state];
			const num_t right_val  = A[right_state];

			B[state] = weight * (left_val + center_val + right_val);
		});

		// -----------------------------------------------------------------
		// Second sweep: update A from B over the interior points
		// -----------------------------------------------------------------
		omp_trav_for_each(trav_A_from_B, [&](auto state) {
			const auto left_state  = state - noarr::idx<'i'>(1);
			const auto right_state = state + noarr::idx<'i'>(1);

			const num_t left_val   = B[left_state];
			const num_t center_val = B[state];
			const num_t right_val  = B[right_state];

			A[state] = weight * (left_val + center_val + right_val);
		});
	});
	#pragma endscop
