	DEFINE_PROTO_STRUCT(a_layout, i_vec);
	DEFINE_PROTO_STRUCT(b_layout, i_vec);
} tuning;

// initialization function
// A[i] = (i + 2) / n
// B[i] = (i + 3) / n
//
// Optimizations:
//  - hoist n and its floating representation out of the loop
//  - avoid recomputing scalar constants in every iteration
void init_array(auto A, auto B) {
	using namespace noarr;

	// spatial problem size (constant for the whole initialization)
	const std::size_t n = A | get_length<'i'>();
	const num_t n_as_num = static_cast<num_t>(n);
	const num_t two      = static_cast<num_t>(2);
	const num_t three    = static_cast<num_t>(3);

	// traverse both arrays with a single traverser to keep them in sync
	traverser(A, B).for_each([&, n_as_num, two, three](auto state) {
		const std::size_t i = get_index<'i'>(state);
		const num_t idx     = static_cast<num_t>(i);

		// NOTE: we keep the division formulation to preserve numerical behaviour,
		//       only the denominator's conversion is hoisted.
		A[state] = (idx + two)   / n_as_num;
		B[state] = (idx + three) / n_as_num;
	});
}

// computation kernel:
// classic 1D Jacobi stencil:
//   B[i] = (A[i-1] + A[i] + A[i+1]) * 0.33333
//   A[i] = (B[i-1] + B[i] + B[i+1]) * 0.33333
//
// Optimizations:
//  - hoist spatial size and interior slice outside the time loop
//  - hoist the constant coefficient and neighbor offset
//  - factor the per-sweep logic into a reusable lambda `sweep`
//  - keep all data traversal expressed via Noarr traversers
[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_1d(int tsteps, auto A, auto B) {
	using namespace noarr;

	// spatial problem size
	const std::size_t n = A | get_length<'i'>();

	// structure used only to iterate over time steps
	auto time_struct = noarr::scalar<num_t>() ^ noarr::vector<'t'>(tsteps);

	// view selecting interior points i in [1, n-2]
	const auto interior = noarr::slice<'i'>(1, n - 2);

	// Jacobi weighting coefficient (kept exactly as in the original kernel)
	const num_t weight = static_cast<num_t>(0.33333);

	// one-step neighbor offset along the i-dimension
	const auto delta = noarr::idx<'i'>(1);

	// one spatial sweep: dst[i] = weight * (src[i-1] + src[i] + src[i+1])
	//
	// Implemented generically so it can be used for:
	//  - B <= A in the first sweep
	//  - A <= B in the second sweep
	auto sweep = [&](auto &dst, auto &src) {
		traverser(dst, src)
			.order(interior) // restrict to interior points only
			.for_each([&, weight, delta](auto state) {
				// construct neighbor states once per element
				const auto left  = state - delta;
				const auto right = state + delta;

				// load neighbors; compiler is expected to keep these in registers
				const num_t left_val   = src[left];
				const num_t center_val = src[state];
				const num_t right_val  = src[right];

				dst[state] = weight * (left_val + center_val + right_val);
			});
	};

