	// traverse the artificial time dimension; each iteration performs
	// two full spatial sweeps (Jacobi scheme)
	traverser(time_struct).for_each([&](auto /*t_state*/) {
		// first sweep: update B from A
		sweep(B, A);

		// second sweep: update A from B
		sweep(A, B);
	});
	#pragma endscop
