void kernel_jacobi_1d(int tsteps, auto A, auto B) {
	using namespace noarr;

	// spatial problem size
	const auto n = A | get_length<'i'>();

	// structure used only to iterate over time steps
	auto time_struct = noarr::scalar<num_t>() ^ noarr::vector<'t'>(tsteps);

	// length of interior region: i in [1, n-2]
	const std::size_t interior_len = (n >= 2) ? (n - 2) : 0;

	// Pre-build views for the first sweep: B <- A
	//
	// For local index k in [0, interior_len):
	//   - A_left[k]  = A[0 + k]     = A[i-1]
	//   - A_mid[k]   = A[1 + k]     = A[i]
	//   - A_right[k] = A[2 + k]     = A[i+1]
	//   - B_mid[k]   = B[1 + k]     = B[i]
	//
	// where i = k + 1 is the original global index in [1, n-2].
	auto A_mid   = A ^ noarr::slice<'i'>(1, interior_len); // A[1..n-2]
	auto A_left  = A ^ noarr::slice<'i'>(0, interior_len); // A[0..n-3]
	auto A_right = A ^ noarr::slice<'i'>(2, interior_len); // A[2..n-1]
	auto B_mid   = B ^ noarr::slice<'i'>(1, interior_len); // B[1..n-2]

	// For the second sweep: A <- B we need analogous views on B
	auto B_left  = B ^ noarr::slice<'i'>(0, interior_len); // B[0..n-3]
	auto B_right = B ^ noarr::slice<'i'>(2, interior_len); // B[2..n-1]
	// A_mid can be reused as the interior of A

	const num_t w = static_cast<num_t>(0.33333);

	#pragma scop
	traverser(time_struct).for_each([=](auto /*t_state*/) {
		// ------------------------------------------------------------------
		// First sweep: update B from A
		// ------------------------------------------------------------------
		//
		// This traverser iterates over the interior indices once, providing
		// the same local 'i' for all four views. The underlying mappings
		// ensure that:
		//   B_mid[s] = w * (A_left[s] + A_mid[s] + A_right[s])
		// corresponds exactly to:
		//   B[i] = w * (A[i-1] + A[i] + A[i+1]) for i in [1, n-2].
		traverser(B_mid, A_mid, A_left, A_right).for_each([=](auto state) {
			const num_t a0 = A_left[state];
			const num_t a1 = A_mid[state];
			const num_t a2 = A_right[state];

			B_mid[state] = w * (a0 + a1 + a2);
		});

		// ------------------------------------------------------------------
		// Second sweep: update A from B
		// ------------------------------------------------------------------
		//
		// Symmetric to the first sweep; now:
		//   A_mid[s] = w * (B_left[s] + B_mid[s] + B_right[s])
		// i.e.
		//   A[i] = w * (B[i-1] + B[i] + B[i+1]) for i in [1, n-2].
		traverser(A_mid, B_mid, B_left, B_right).for_each([=](auto state) {
			const num_t b0 = B_left[state];
			const num_t b1 = B_mid[state];
			const num_t b2 = B_right[state];

			A_mid[state] = w * (b0 + b1 + b2);
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size and number of time steps
	std::size_t n = N;
	std::size_t tsteps = TSTEPS;

	// set the length of the spatial dimension
	auto set_lengths = noarr::set_length<'i'>(n);

	// allocate bags for A and B
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize arrays
	init_array(A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_jacobi_1d(static_cast<int>(tsteps), A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to inhibit dead-code elimination in benchmarks)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
